  const inline = useMutation({
    mutationFn: ({ c, amount }: { c: Claim; amount: string }) =>
      putJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(c.id)}`,
