p='features/rates/rates.slot.tsx'; s=open(p).read()
def sub(a,b):
    global s
    assert s.count(a)==1,a
    s=s.replace(a,b)
sub("import { useClaims } from '../claims/claims';","import { counts, useClaims, useTagsUsed } from '../claims/claims';")
sub("import { GRADES, liveHolds, usePeople } from '../people/people';","import { GRADES, gradeOn, liveHolds, usePeople } from '../people/people';")
sub("import { NA, PCT, personDueTotal,","import { NA, PCT, claimDue, personDueTotal,")
sub("""export const contributions = [""","""// For every tag ever used on the sheet, its due-total: the due of the claims that count which carry
// it, added up, skipping n/a (a claim with two tags counts in both).
function TagTotals({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const tags = useTagsUsed(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const dues = people.flatMap((p) =>
    claims
      .filter((c) => c.personId === p.id && c.tags.length > 0 && counts(c, liveHolds(p, today), today))
      .map((c) => ({ tags: c.tags, due: claimDue(c, rateOn(rates, gradeOn(p.grades, c.date), c.date), floor, late, gradeOn(p.grades, c.date)) })),
  );
  if (tags.length === 0) return null;
  return (
    <section data-testid="tag-totals">
      <h3>Due by tag</h3>
      <ul>
        {tags.map((t) => (
          <li key={t}>
            {t}: <strong data-testid={`tag-${t}-due-total`}>{sumDue(dues.filter((d) => d.tags.includes(t)).map((d) => d.due))}</strong>
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contributions = [
  SheetBody.fill({ order: 20.6, Component: TagTotals }),""")
open(p,'w').write(s)
EOF
